def unique():
    # 4 log_8 r = v (정수) <=> r^4 = 8^v = 2^(3v)
    def is_pow2(m):
        return m > 0 and m & (m - 1) == 0
    good = []
    for n in range(1, 1001):
        r4 = Fraction(n + 1, 40) ** 4
        a, b = r4.numerator, r4.denominator
        if b == 1 and is_pow2(a) and (a.bit_length() - 1) % 3 == 0:
            good.append(n)
        elif a == 1 and is_pow2(b) and (b.bit_length() - 1) % 3 == 0:
            good.append(n)
    return [sum(good)]
